const K = 100;
const COS = Math.cos((51.2 * Math.PI) / 180);

/** Project WGS84 coordinates into the outline's coordinate space. */
export function project(lat: number, lng: number): { x: number; y: number } {
  return { x: Math.round((lng - 5.8) * COS * K * 10) / 10, y: Math.round((55.1 - lat) * K * 10) / 10 };
}
